{# Segmented "wins per 10" bar: fills round(v/10) of 10 cells. `tone` = free|gated #}
{% macro wins_bar(pct, tone='free') -%}
{% set _filled = ((pct or 0) / 10)|round|int %}
<span class="w10 tone-{{ tone }}" aria-hidden="true">{% for i in range(10) %}<i class="{{ 'on' if i < _filled else '' }}"></i>{% endfor %}</span>
{%- endmacro %}

{# Display supplied percentage-point deltas without rounding a nonzero sign to zero. #}
{% macro comparison_delta(value) -%}
{%- if value is none -%}{{ t('Unavailable', '暂无数据') }}
{%- elif value == 0 -%}0.0
{%- elif value|abs < 0.1 -%}{{ '%+.2g'|format(value) }}
{%- else -%}{{ '%+.1f'|format(value) }}
{%- endif -%}
{%- endmacro %}

.lc-wr-unit{grid-column:1/-1;border-top:1px solid var(--line);padding-top:var(--sp-2,8px)}
.lc-baseline-heading{grid-column:1/-1;font-size:var(--fs-sm,12.5px);line-height:1.45;color:var(--muted);margin-top:var(--sp-2,8px)}
.lc-baselines{grid-column:1/-1;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:var(--sp-3,12px);margin:0;min-width:0}
.lc-baseline-value{margin:0;font:600 20px/1.3 var(--font-mono);font-variant-numeric:tabular-nums;color:var(--text)}
.lc-baseline-value[data-state="positive"]{color:var(--ink-up,var(--up))}
.lc-baseline-value[data-state="negative"]{color:var(--ink-down,var(--down))}
.lc-baseline-value[data-state="missing"]{font:500 var(--fs-body,14px)/1.5 var(--font-ui);color:var(--muted);overflow-wrap:anywhere}
.lc-comparison-period{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}

/* wins-per-10 segmented bar */
.w10{display:inline-flex;gap:3px;vertical-align:middle}
.w10 i{width:10px;height:10px;border-radius:3px;background:color-mix(in srgb,var(--muted) 26%,transparent)}
.w10.tone-free i.on{background:var(--up)}
.w10.tone-gated i.on{background:color-mix(in srgb,var(--muted) 60%,transparent)}

  {% else %}
  <span class="chip">{{ t('Random-entry comparison unavailable', '随机入场比较暂无数据') }}</span>
  {% endif %}
</div>

  {% elif c.edge_train_pp is not none %}
  <span class="chip">{{ t('Recent-period comparison unavailable', '近年时期比较暂无数据') }}</span>
  {% else %}
  <span class="chip">{{ t('Random-entry comparison unavailable', '随机入场比较暂无数据') }}</span>
  {% endif %}
</div>

